{"command":"python3 -c "
import numpy as np, json, subprocess, wave

for rel in [-31]:
    subprocess.run(['ft2', 'call', 'sample_set', json.dumps({
        'instrument': 8, 'sample': 0, 'loop_start': 0, 'loop_length': 32, 'flags': 1, 'volume': 64,
        'relative_note': rel, 'finetune': 0
    })])
    subprocess.run(['ft2', 'call', 'module_render', json.dumps({
        'path': f'/workspace/test_sine_r{rel}.wav', 'rate': 44100, 'bits': 16, 'amp': 1, 'loops': 1
    })])
    with wave.open(f'/workspace/test_sine_r{rel}.wav', 'rb') as w:
        frames = w.readframes(w.getframerate())
        data = np.frombuffer(frames, dtype=np.int16)[0::2]
        fft = np.abs(np.fft.rfft(data[:44100]))
        freqs = np.fft.rfftfreq(44100, 1/44100)
        peak_idx = np.argmax(fft[50:1000]) + 50
        print(f'rel={rel} -> peak freq = {freqs[peak_idx]:.2f} Hz')
""}

