{"command":"python3 -c "
import numpy as np, json, subprocess, wave

# Let's test a few notes with rel=0 on inst 8:
# inst 8 has 32 samples per cycle.
for test_note in ['C-3', 'C-4', 'C-5', 'A-4']:
    subprocess.run(['ft2', 'call', 'pattern_set_cell', json.dumps({
        'pattern': 0, 'row': 0, 'channel': 0, 'note': test_note, 'instrument': 8
    })])
    subprocess.run(['ft2', 'call', 'sample_set', json.dumps({
        'instrument': 8, 'sample': 0, 'loop_start': 0, 'loop_length': 32, 'flags': 1, 'volume': 64,
        'relative_note': 0, 'finetune': 0
    })])
    subprocess.run(['ft2', 'call', 'module_render', json.dumps({
        'path': '/workspace/test_pitch_meas.wav', 'rate': 44100, 'bits': 16, 'amp': 1, 'loops': 1
    })])
    with wave.open('/workspace/test_pitch_meas.wav', 'rb') as w:
        frames = w.readframes(w.getframerate())
        data = np.frombuffer(frames, dtype=np.int16)[0::2]
        fft = np.abs(np.fft.rfft(data[:44100]))
        freqs = np.fft.rfftfreq(44100, 1/44100)
        # Find peak
        peak_idx = np.argmax(fft[20:10000]) + 20
        print(f'note {test_note}: peak freq = {freqs[peak_idx]:.2f} Hz')
""}

