import numpy as np, base64, json, subprocess, wave

# Instrument 1 has 440 cycles at sr=8363.
# With relative_note = 12:
subprocess.run(['ft2', 'call', 'sample_set', json.dumps({
    'instrument': 1, 'sample': 0, 'loop_start': 0, 'loop_length': 8363, 'flags': 1,
