})])

# Let's test notes C-4 (49), E-4 (53), G-4 (56), A-4 (58), C-5 (61):
notes = [('C-4', 49), ('E-4', 53), ('G-4', 56), ('A-4', 58), ('C-5', 61)]
for name, note_num in notes:
    subprocess.run(['ft2', 'call', 'pattern_clear', json.dumps({'pattern': 0})])
    subprocess.run(['ft2', 'call', 'pattern_set_cell', json.dumps({
        'pattern': 0, 'row': 0, 'channel': 0, 'note': note_num, 'instrument': 1
    })])
    subprocess.run(['ft2', 'call', 'module_render', json.dumps({
        'path': f'/workspace/test_tuning_{name}.wav', 'rate': 44100, 'bits': 16, 'amp': 1, 'loops': 1
    })])
    with wave.open(f'/workspace/test_tuning_{name}.wav', 'rb') as w:
        frames = w.readframes(w.getframerate())
        data = np.frombuffer(frames, dtype=np.int16)[0::2]
        fft = np.abs(np.fft.rfft(data[:44100]))
        freqs = np.fft.rfftfreq(44100, 1/44100)
        peak_idx = np.argmax(fft[100:2000]) + 100
        print(f'{name} (note {note_num}): peak = {freqs[peak_idx]:.2f} Hz')
""}

