import numpy as np, base64, json, subprocess, wave

# Suppose we generate a sample at sr = 16726.
# If note C-4 is 261.625565 Hz.
# What relative_note makes note C-4 play at 261.625565 Hz?
# Let's test relative_note from -12 to +12:
sr = 16726
t = np.arange(sr) / sr
sine = (np.sin(2 * np.pi * 261.625565 * t) * 32767).astype(np.int16)

subprocess.run(['ft2', 'call', 'sample_create_from_pcm', json.dumps({
    'instrument': 11, 'sample': 0, 'pcm': base64.b64encode(sine.tobytes()).decode('ascii'),
    'encoding': 'int16', 'name': 'sine_c4_16k'
})])

for r in [-12, -9, -6, -3, 0, 3, 6, 9, 12]:
    subprocess.run(['ft2', 'call', 'sample_set', json.dumps({
        'instrument': 11, 'sample': 0, 'loop_start': 0, 'loop_length': sr, 'flags': 1,
        'volume': 64, 'relative_note': r, 'finetune': 0
    })])
    subprocess.run(['ft2', 'call', 'pattern_clear', json.dumps({'pattern': 0})])
    subprocess.run(['ft2', 'call', 'pattern_set_cell', json.dumps({
        'pattern': 0, 'row': 0, 'channel': 0, 'note': 'C-4', 'instrument': 11
    })])
    subprocess.run(['ft2', 'call', 'module_render', json.dumps({
        'path': f'/workspace/test_c4_r{r}.wav', 'rate': 44100, 'bits': 16, 'amp': 1, 'loops': 1
    })])
    with wave.open(f'/workspace/test_c4_r{r}.wav', 'rb') as w:
        frames = w.readframes(w.getframerate())
        data = np.frombuffer(frames, dtype=np.int16)[0::2]
        fft = np.abs(np.fft.rfft(data[:44100]))
        freqs = np.fft.rfftfreq(44100, 1/44100)
        peak_idx = np.argmax(fft[50:1000]) + 50
        print(f'r={r:3d}: peak = {freqs[peak_idx]:.2f} Hz')
""}

